  "answer": {
    "kind": "student",
    "resposta": "",
    "raciocinio": "O problema tem três causas: ausência de timeout (a requisição fica pendente
indefinidamente), falta de verificação de status HTTP e ausência de retry
para falhas transitórias.

Para o timeout, usei Promise.race com uma Promise que rejeita após 3 segundos.
Isso é simples e eficaz: se o fetch demorar mais que TIMEOUT_MS, a Promise de
timeout vence a corrida e a função recebe o erro de timeout.

Para retry, implementei um loop while que repete a tentativa até MAX_RETRIES
vezes quando qualquer erro ocorre. Se após todas as tentativas ainda houver
erro, ele é relançado com mensagem descritiva.

Valido que a taxa existe antes de retornar, evitando retornar undefined.
O GET é idempotente, então retry é seguro. O trade-off é a latência adicional
de até 3 segundos por tentativa extra.
",
    "codigo": "// exchange-rate.js

const API_BASE_URL = 'https://api.exchangerates.example.com';
const TIMEOUT_MS  = 3000;
const MAX_RETRIES = 1;

function timeoutPromise(ms) {
  return new Promise((_, reject) =>
    setTimeout(() => reject(new Error(`Request timed out after ${ms}ms`)), ms)
  );
}

async function getExchangeRate(fromCurrency, toCurrency) {
  const url = `${API_BASE_URL}/latest?base=${fromCurrency}&symbols=${toCurrency}`;
  let attempts = 0;

  while (attempts <= MAX_RETRIES) {
    attempts++;
    try {
      const response = await Promise.race([
        fetch(url),
        timeoutPromise(TIMEOUT_MS),
      ]);

      const data = await response.json();
      const rate = data.rates[toCurrency];

      if (!rate) {
        throw new Error(`Rate not found for ${toCurrency}`);
      }

      return rate;

    } catch (err) {
      if (attempts > MAX_RETRIES) {
        throw new Error(`Failed to fetch exchange rate: ${err.message}`);
      }
    }
  }
}

module.exports = { getExchangeRate, TIMEOUT_MS, MAX_RETRIES };
",
